'use strict';
function categoryBadge(name){const c=Categories.appearance(state,name);return `<span class="tag category-badge" style="border-left:4px solid ${c.color};background:${c.color}16;color:var(--ink,#243344)"><span aria-hidden="true">${esc(c.symbol)}</span> ${esc(name)}</span>`;}
function categories(){const items=Categories.validate(state.categories);return `<section class="card"><div class="card-head"><div><h2>Suas categorias</h2><p>Escolha um símbolo e uma cor para identificar receitas e despesas.</p></div><button class="primary" data-new-category>+ Nova categoria</button></div><div class="category-cards">${items.map(c=>`<article class="category-item">${categoryBadge(c.name)}<div class="actions"><button data-edit-category="${esc(c.id)}">Editar</button><button data-delete-category="${esc(c.id)}">Excluir</button></div></article>`).join('')||'<p>Nenhuma categoria cadastrada. Os lançamentos antigos continuam preservados.</p>'}</div></section>`;}
function openCategory(id){const f=$('#category-form');f.querySelector('.form-message')?.remove();f.reset();const c=Categories.validate(state.categories).find(c=>c.id===id);f.elements.id.value=c?.id||'';f.elements.name.value=c?.name||'';f.elements.symbol.value=c?.symbol||'🏷️';f.elements.color.value=c?.color||'#4876b8';$('#category-title').textContent=c?'Editar categoria':'Nova categoria';$('#category-dialog').showModal();}
function updateCategoryOptions(){const input=$('#entry-form').elements.category;input.removeAttribute('list');input.readOnly=false;input.disabled=false;hideCategoryChoices();}
let categoryChoiceIndex=-1,categoryChoices=[];
const categoryInput=$('#entry-form').elements.category;
const categoryBox=document.createElement('div');categoryBox.className='category-picker';categoryInput.parentNode.insertBefore(categoryBox,categoryInput);categoryBox.append(categoryInput);
categoryInput.removeAttribute('list');categoryInput.autocomplete='off';categoryInput.setAttribute('role','combobox');categoryInput.setAttribute('aria-autocomplete','list');categoryInput.setAttribute('aria-controls','category-choices');categoryInput.setAttribute('aria-expanded','false');
const clearCategory=document.createElement('button');clearCategory.type='button';clearCategory.className='category-clear';clearCategory.textContent='×';clearCategory.setAttribute('aria-label','Limpar categoria');categoryBox.append(clearCategory);
const categoryChoicesBox=document.createElement('div');categoryChoicesBox.id='category-choices';categoryChoicesBox.className='category-choices';categoryChoicesBox.setAttribute('role','listbox');categoryChoicesBox.setAttribute('aria-label','Categorias sugeridas');categoryChoicesBox.hidden=true;categoryBox.append(categoryChoicesBox);
function hideCategoryChoices(){categoryChoicesBox.hidden=true;categoryInput.setAttribute('aria-expanded','false');categoryInput.removeAttribute('aria-activedescendant');categoryChoiceIndex=-1;}
function paintCategoryChoices(){categoryChoicesBox.innerHTML=categoryChoices.map((c,i)=>`<button type="button" tabindex="-1" role="option" id="category-option-${i}" aria-selected="${i===categoryChoiceIndex}" data-category-choice="${i}"><span style="color:${c.color}" aria-hidden="true">${esc(c.symbol)} ●</span> ${esc(c.name)}</button>`).join('')||'<p>Nome novo: você pode digitá-lo e salvar o lançamento, ou cadastrar uma categoria no menu Categorias.</p>';categoryChoicesBox.hidden=false;categoryInput.setAttribute('aria-expanded','true');if(categoryChoiceIndex<0)categoryInput.removeAttribute('aria-activedescendant');if(categoryChoiceIndex>=0){categoryInput.setAttribute('aria-activedescendant','category-option-'+categoryChoiceIndex);categoryChoicesBox.querySelector('[aria-selected="true"]')?.scrollIntoView({block:'nearest'});}}
function showCategoryChoices(all=false){categoryChoiceIndex=-1;categoryChoices=Categories.options(state,all?'':categoryInput.value);paintCategoryChoices();}
function chooseCategory(index){const c=categoryChoices[index];if(!c)return;categoryInput.value=c.name;categoryInput.focus();hideCategoryChoices();}
categoryInput.addEventListener('focus',()=>showCategoryChoices(true));categoryInput.addEventListener('input',()=>showCategoryChoices());
categoryInput.addEventListener('keydown',e=>{if(e.key==='Escape'&&!categoryChoicesBox.hidden){e.preventDefault();e.stopPropagation();hideCategoryChoices();}if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();if(categoryChoicesBox.hidden)showCategoryChoices(true);if(!categoryChoices.length)return;categoryChoiceIndex=(categoryChoiceIndex+(e.key==='ArrowDown'?1:-1)+categoryChoices.length)%categoryChoices.length;paintCategoryChoices();}if(e.key==='Enter'&&!categoryChoicesBox.hidden&&categoryChoiceIndex>=0){e.preventDefault();chooseCategory(categoryChoiceIndex);}});
categoryChoicesBox.addEventListener('pointerdown',e=>e.preventDefault());categoryChoicesBox.addEventListener('click',e=>{const b=e.target.closest('[data-category-choice]');if(b)chooseCategory(Number(b.dataset.categoryChoice));});
clearCategory.addEventListener('click',()=>{categoryInput.value='';categoryInput.focus();showCategoryChoices(true);});categoryBox.addEventListener('focusout',e=>{if(!categoryBox.contains(e.relatedTarget))hideCategoryChoices();});
$('#entry-form').addEventListener('reset',hideCategoryChoices);
document.addEventListener('click',safe(async e=>{const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-new-category'))openCategory();if(b.dataset.editCategory)openCategory(b.dataset.editCategory);if(b.dataset.deleteCategory&&confirm('Excluir a categoria do cadastro? Os lançamentos existentes serão mantidos.'))await save(Categories.remove(state,b.dataset.deleteCategory));}));
$('#category-form').onsubmit=safe(async e=>{e.preventDefault();const f=e.target;await save(Categories.upsert(state,{id:f.elements.id.value||newId(),name:f.elements.name.value,symbol:f.elements.symbol.value,color:f.elements.color.value}));updateCategoryOptions();$('#category-dialog').close();});
